#include <climits>

// Priority queue to store {distance, node} pairs, sorted by distance
std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;

// Initialize distance array with a large value
for (int i = 0; i < n; i++) {
    dist[i] = INT_MAX;
}

// Distance to start node is 0
dist[start] = 0;
pq.push({0, start});

// Process nodes until queue is empty
while (!pq.empty()) {
    int u = pq.top().second;
    int d = pq.top().first;
    pq.pop();

    // Skip if we've already found a better distance
    if (d > dist[u]) continue;

    // Check neighbors
    for (int v = 0; v < n; v++) {
        // If there is an edge from u to v
        if (graph[u][v] != 0) {
            int new_dist = dist[u] + graph[u][v];
            if (new_dist < dist[v]) {
                dist[v] = new_dist;
                pq.push({new_dist, v});
            }
        }
    }
}

